steps.body:
`indexOf` and `includes` check every item, which is O(n). A **sorted** array lets you skip most of them: look at the middle item, and if the target is bigger, nothing in the left half can match. Each step throws away half of what is left, so a million items take about 20 steps.

```javascript
function binarySearch(arr, target) {
  let lo = 0;
  let hi = arr.length - 1;
  while (lo <= hi) {
    const mid = Math.floor((lo + hi) / 2);
    if (arr[mid] === target) {
      return mid;
    }
    if (arr[mid] < target) {
      lo = mid + 1;
    } else {
      hi = mid - 1;
    }
  }
  return -1;
}
console.log(binarySearch([2, 5, 8, 12, 16], 12)); // 3
console.log(binarySearch([2, 5, 8, 12, 16], 7)); // -1
```

`lo` and `hi` are the first and last index that could still hold the target. The loop runs while that range is not empty (`lo <= hi`), and `mid + 1` or `mid - 1` drops the middle once it has been checked, so the range shrinks every time. `Math.floor` keeps `mid` a whole index. `<` compares strings too, so the same function searches a sorted list of words.

**The gotcha:** the array must be sorted in the order you compare with. Numbers sorted by plain `sort()` come out as `[1, 10, 2]`, and a binary search over that misses values that are there, without any error.

example.code:
const input = require("fs").readFileSync(0, "utf8");
const [first, ...queries] = input.trim().split("\n");
const prices = first.trim().split(/\s+/).map(Number);

function search(arr, target) {
  let lo = 0;
  let hi = arr.length - 1;
  let steps = 0;
  while (lo <= hi) {
    steps++;
    const mid = Math.floor((lo + hi) / 2);
    if (arr[mid] === target) {
      return [mid, steps];
    }
    if (arr[mid] < target) {
      lo = mid + 1;
    } else {
      hi = mid - 1;
    }
  }
  return [-1, steps];
}

for (const q of queries) {
  const target = Number(q);
  const [index, steps] = search(prices, target);
  if (index === -1) {
    console.log(`${target} not found, steps ${steps}`);
  } else {
    console.log(`${target} at index ${index}, steps ${steps}`);
  }
}

