      if (arr[mid] < target && target <= arr[hi]) {
        lo = mid + 1;
      } else {
        hi = mid - 1;
      }
    }
  }
  return -1;
}

for (const q of queries) {
  const target = Number(q);
  const index = searchRotated(shelves, target);
  if (index === -1) {
    console.log(`${target} not found`);
  } else {
    console.log(`${target} at index ${index}`);
  }
}

